type TreeNode = { v: number; L: TreeNode | null; R: TreeNode | null };
// Level-order array, null for a missing child.
function buildTree(values: (number | null)[]): TreeNode | null {
  if (!values.length || values[0] == null) return null;
  const root: TreeNode = { v: values[0], L: null, R: null };
  const q = [root];
  let i = 1;
  while (q.length && i < values.length) {
    const cur = q.shift()!;
    const l = values[i++];
    if (l != null) { cur.L = { v: l, L: null, R: null }; q.push(cur.L); }
    const r = values[i++];
    if (r != null) { cur.R = { v: r, L: null, R: null }; q.push(cur.R); }
  }
  return root;
}

function kthSmallest(root: TreeNode | null, k: number): number | null {
  const stack: TreeNode[] = [];
  let cur = root;
  let seen = 0;
  while (cur || stack.length) {
    while (cur) { stack.push(cur); cur = cur.L; }
    const n = stack.pop()!;
    if (++seen === k) return n.v;
    cur = n.R;
  }
  return null;
}

function kthLatencyFrom(values: (number | null)[], k: number): number | null {
  return kthSmallest(buildTree(values), k);
}
